//! Acceptance tests for the editing commands. Every fixture is generated by code.

use crate::loudness;
use ferraus_core::exec::apply_spec;
use ferraus_core::prelude::*;
use ferraus_core::testing::{self, args, noise, read_wav, sine, stereo, write_wav, TempDir};
use ferraus_core::{OpCtx, Runner};
use proptest::prelude::*;
use std::path::PathBuf;

// ---------------------------------------------------------------------------------------
// helpers
// ---------------------------------------------------------------------------------------

fn op(name: &str) -> OpSpec {
    crate::ops().into_iter().find(|o| o.name == name).unwrap_or_else(|| panic!("no op {name}"))
}

/// Run a transform and keep the context (warnings, metrics, notes).
fn run_tc(
    name: &str,
    pairs: &[(&str, &str)],
    buf: AudioBuffer,
    setup: impl FnOnce(&mut OpCtx),
) -> (Result<AudioBuffer>, OpCtx<'static>) {
    let spec = op(name);
    let a = args(&spec, pairs);
    let mut c = testing::ctx();
    c.command = name.to_string();
    setup(&mut c);
    let r = apply_spec(&spec, &a, buf, &mut c);
    (r, c)
}

fn run_t(name: &str, pairs: &[(&str, &str)], buf: AudioBuffer) -> (Result<AudioBuffer>, OpCtx<'static>) {
    run_tc(name, pairs, buf, |_| {})
}

fn ok_t(name: &str, pairs: &[(&str, &str)], buf: AudioBuffer) -> AudioBuffer {
    run_t(name, pairs, buf).0.unwrap()
}

fn err_code(r: Result<AudioBuffer>) -> i32 {
    r.expect_err("expected an error").exit_code
}

fn has_warning(c: &OpCtx, code: &str) -> bool {
    c.warnings.iter().any(|w| w.code == code)
}

/// Run a custom op on inputs written to a temp dir; `output` is a file name inside it.
fn run_custom(
    name: &str,
    pairs: &[(&str, &str)],
    inputs: &[AudioBuffer],
    output: Option<&str>,
    setup: impl FnOnce(&mut OpCtx),
) -> (Result<Value>, OpCtx<'static>, TempDir) {
    let names: Vec<String> = (0..inputs.len()).map(|i| format!("in{i}.wav")).collect();
    let named: Vec<(&str, &AudioBuffer)> = names.iter().map(|n| n.as_str()).zip(inputs).collect();
    run_custom_named(name, pairs, &named, output, setup)
}

/// [`run_custom`] with the inputs written under the given file names.
fn run_custom_named(
    name: &str,
    pairs: &[(&str, &str)],
    inputs: &[(&str, &AudioBuffer)],
    output: Option<&str>,
    setup: impl FnOnce(&mut OpCtx),
) -> (Result<Value>, OpCtx<'static>, TempDir) {
    let spec = op(name);
    let dir = TempDir::new(&name.replace(' ', "-"));
    let paths: Vec<PathBuf> = inputs
        .iter()
        .map(|(file, b)| {
            let p = dir.path(file);
            write_wav(&p, b);
            p
        })
        .collect();
    let a = args(&spec, pairs);
    let mut c = testing::ctx();
    c.command = spec.name.to_string();
    c.inputs = paths;
    c.globals.output = output.map(|o| dir.path(o).display().to_string());
    setup(&mut c);
    let f = match spec.runner {
        Runner::Custom(f) => f,
        _ => panic!("{name} is not a custom op"),
    };
    let r = f(&a, &mut c);
    (r, c, dir)
}

fn db(x: f64) -> f32 {
    db_to_lin(x) as f32
}

/// Click detector: the largest first difference (a high-pass) within 2 ms of `boundary`
/// relative to the largest first difference elsewhere (more than 10 ms away). Samples before
/// the start of `x` count as silence. Clean edits read about 1; a click reads several times
/// higher.
fn click_ratio(x: &[f32], boundary: usize, sr: u32) -> f64 {
    let d = |i: usize| -> f32 {
        let prev = if i == 0 { 0.0 } else { x[i - 1] };
        (x[i] - prev).abs()
    };
    let near_w = (0.002 * sr as f64) as usize;
    let excl = (0.010 * sr as f64) as usize;
    let near = (boundary.saturating_sub(near_w)..(boundary + near_w).min(x.len())).map(d).fold(0.0f32, f32::max);
    let rest = (0..x.len()).filter(|i| i.abs_diff(boundary) > excl).map(d).fold(0.0f32, f32::max);
    near as f64 / (rest as f64).max(1e-9)
}

/// Pink-ish noise (Paul Kellet's filter on white noise).
#[allow(clippy::excessive_precision)]
fn pink(sr: u32, secs: f64, amp: f32, seed: u64) -> AudioBuffer {
    let w = noise(sr, secs, 1.0, seed);
    let mut b = [0f32; 7];
    let x: Vec<f32> = w.data[0]
        .iter()
        .map(|&v| {
            b[0] = 0.99886 * b[0] + v * 0.0555179;
            b[1] = 0.99332 * b[1] + v * 0.0750759;
            b[2] = 0.96900 * b[2] + v * 0.1538520;
            b[3] = 0.86650 * b[3] + v * 0.3104856;
            b[4] = 0.55000 * b[4] + v * 0.5329522;
            b[5] = -0.7616 * b[5] - v * 0.0168980;
            let p = b.iter().sum::<f32>() + v * 0.5362;
            b[6] = v * 0.115926;
            p * 0.11 * amp
        })
        .collect();
    AudioBuffer::from_mono(sr, x)
}

fn concat_bufs(parts: &[AudioBuffer]) -> AudioBuffer {
    let mut out = parts[0].clone();
    for p in &parts[1..] {
        out.append(p);
    }
    out
}

fn silence(sr: u32, secs: f64) -> AudioBuffer {
    AudioBuffer::new(sr, 1, (sr as f64 * secs).round() as usize)
}

