#[test]
fn every_op_is_documented() {
    let ops = crate::ops();
    let names: Vec<&str> = ops.iter().map(|o| o.name).collect();
    for want in [
        "trim",
        "cut",
        "split",
        "concat",
        "resample",
        "gain",
        "normalize",
        "channels",
        "silence detect",
        "silence trim",
        "silence pad",
        "mix",
        "mix balance",
        "waveform",
        "spectrogram",
    ] {
        assert!(names.contains(&want), "missing {want}");
    }
    for o in &ops {
        assert!(!o.about.is_empty(), "{} has no about", o.name);
        assert!(o.examples.len() >= 2, "{} needs 2 examples", o.name);
        for e in &o.examples {
            assert!(e.cmd.starts_with(&format!("ferraus {}", o.name)) || e.cmd.starts_with("ferraus fx"), "{}", e.cmd);
        }
        for p in &o.params {
            assert!(!p.help.is_empty(), "{} --{} has no help", o.name, p.name);
            assert!(
                ![
                    "output",
                    "format",
                    "channels",
                    "sample-rate",
                    "bit-depth",
                    "bitrate",
                    "threads",
                    "seed",
                    "bpm",
                    "force"
                ]
                .contains(&p.name),
                "{} --{} collides with a global flag",
                o.name,
                p.name
            );
        }
    }
    // registering twice in one registry would panic on duplicates
    let _ = testing::leak_registry(crate::ops());
}

// ---------------------------------------------------------------------------------------
// trim
// ---------------------------------------------------------------------------------------

#[test]
fn trim_exact_without_snap() {
    let b = sine(48000, 440.0, 2.0, 0.5);
    let out = ok_t("trim", &[("range", "0.5s..1.5s"), ("snap", "off")], b.clone());
    assert_eq!(out, b.slice(24000, 72000));
    // beats resolve through --bpm
    let (out, _) = run_tc("trim", &[("range", "2b..4b"), ("snap", "off")], b.clone(), |c| c.globals.bpm = Some(120.0));
    assert_eq!(out.unwrap(), b.slice(48000, 96000));
    // negative times count from the end
    let out = ok_t("trim", &[("range", "-0.25s..end"), ("snap", "off")], b.clone());
    assert_eq!(out.frames(), 12000);
}

#[test]
fn trim_snaps_to_zero_and_does_not_click() {
    let sr = 48000;
    let b = sine(sr, 1000.0, 2.0, 0.8);
    let (out, c) = run_t("trim", &[("range", "0.30731s..1.21377s"), ("pad", "50ms")], b.clone());
    let out = out.unwrap();
    assert!(c.notes.contains_key("start_s"));
    let pad = 2400;
    let x = &out.data[0];
    let len = out.frames() - 2 * pad;
    assert!(len.abs_diff((1.21377f64 * 48000.0).round() as usize - (0.30731f64 * 48000.0).round() as usize) <= 2 * 240);
    let r1 = click_ratio(x, pad, sr);
    let r2 = click_ratio(x, pad + len, sr);
    assert!(r1 < 1.5 && r2 < 1.5, "click ratios {r1} {r2}");
    // the detector itself catches the hard cut that --snap off produces at a waveform peak
    let hard = ok_t("trim", &[("range", "0.30025s..1.2s"), ("snap", "off"), ("pad", "50ms")], b);
    let r = click_ratio(&hard.data[0], pad, sr);
    assert!(r > 3.0, "detector should flag a hard cut, ratio {r}");
}

#[test]
fn trim_stereo_without_common_zero_crossing_does_not_click() {
    let sr = 48000;
    let l = sine(sr, 1000.0, 1.0, 0.8);
    let r: Vec<f32> = (0..sr as usize)
        .map(|i| 0.8 * (2.0 * std::f64::consts::PI * 1000.0 * i as f64 / sr as f64).cos() as f32)
        .collect();
    let b = AudioBuffer::from_planar(sr, vec![l.data[0].clone(), r]);
    let (out, c) = run_t("trim", &[("range", "0.2s..0.7s"), ("pad", "20ms")], b);
    let out = out.unwrap();
    assert!(c.notes.contains_key("edge_fades"));
    let pad = 960;
    let len = out.frames() - 2 * pad;
    for ch in &out.data {
        assert!(click_ratio(ch, pad, sr) < 1.5);
        assert!(click_ratio(ch, pad + len, sr) < 1.5);
    }
}

#[test]
fn trim_padding_and_edge_cases() {
    let b = sine(8000, 200.0, 1.0, 0.5);
    let out =
        ok_t("trim", &[("range", "0s..0.5s"), ("snap", "off"), ("pad", "100ms"), ("pad-end", "250ms")], b.clone());
    assert_eq!(out.frames(), 800 + 4000 + 2000);
    assert!(out.data[0][..800].iter().all(|v| *v == 0.0));
    assert!(out.data[0][4800..].iter().all(|v| *v == 0.0));
    // start after end: usage error (exit 2)
    assert_eq!(err_code(run_t("trim", &[("range", "0.8s..0.2s")], b.clone()).0), 2);
    // start beyond the end of the input
    assert_eq!(err_code(run_t("trim", &[("range", "3s..4s")], b.clone()).0), 2);
    // end beyond the end: clamped with a warning
    let (out, c) = run_t("trim", &[("range", "0.5s..9s"), ("snap", "off")], b.clone());
    assert_eq!(out.unwrap().frames(), 4000);
    assert!(has_warning(&c, "range_clamped"));
    // empty and very short inputs
    let (out, c) = run_t("trim", &[("range", "0s..1s"), ("pad", "10ms")], AudioBuffer::new(8000, 2, 0));
    assert_eq!(out.unwrap().frames(), 160);
    assert!(has_warning(&c, "empty_input"));
    let tiny = AudioBuffer::from_mono(8000, vec![0.1, 0.2, 0.3]);
    let out = ok_t("trim", &[("range", "1smp..2smp")], tiny);
    assert!(out.frames() <= 3);
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(96))]

    #[test]
    fn trim_length_property(
        len_ms in 0u32..1500,
        a in 0.0f64..1.0,
        b in 0.0f64..1.0,
        snap in any::<bool>(),
        freq in 30.0f64..3000.0,
        stereo_in in any::<bool>(),
    ) {
        let sr = 8000;
        let mut buf = sine(sr, freq, len_ms as f64 / 1000.0, 0.7);
        if stereo_in {
            buf = stereo(buf);
        }
        let n = buf.frames();
        let (lo, hi) = if a <= b { (a, b) } else { (b, a) };
        let (s, e) = ((lo * n as f64) as usize, (hi * n as f64) as usize);
        let range = format!("{s}smp..{e}smp");
        let pairs = [("range", range.as_str()), ("snap", if snap { "zero" } else { "off" })];
        let (r, _) = run_t("trim", &pairs, buf);
        match r {
            Ok(out) => {
                let w = if snap { (0.005 * sr as f64).round() as usize } else { 0 };
                prop_assert!(out.frames().abs_diff(e - s) <= 2 * w, "len {} want {}", out.frames(), e - s);
            }
            Err(err) => {
                // only a start at/after the end of a non-empty input may fail
                prop_assert_eq!(err.exit_code, 2);
                prop_assert!(n > 0 && s >= n);
            }
        }
    }

    #[test]
    fn trim_reversed_range_is_usage_error(s in 1usize..4000, d in 1usize..4000) {
        let buf = sine(8000, 440.0, 1.0, 0.5);
        let range = format!("{}smp..{}smp", s + d, s);
        let (r, _) = run_t("trim", &[("range", range.as_str())], buf);
        prop_assert_eq!(r.unwrap_err().exit_code, 2);
    }
}

