#[test]
fn cut_joins_without_clicks() {
    let sr = 48000;
    let b = stereo(sine(sr, 440.0, 2.0, 0.8));
    let (out, c) = run_t("cut", &[("range", "0.5003s..0.71s"), ("range", "1.2s..1.3333s")], b.clone());
    let out = out.unwrap();
    let r1 = (0.5003f64 * 48000.0).round() as usize;
    let r1e = (0.71f64 * 48000.0).round() as usize;
    let r2 = 57600usize;
    let r2e = (1.3333f64 * 48000.0).round() as usize;
    assert_eq!(out.frames(), 96000 - (r1e - r1) - (r2e - r2));
    assert!(c.notes.contains_key("removed"));
    let join1 = r1;
    let join2 = r2 - (r1e - r1);
    for ch in &out.data {
        let a = click_ratio(ch, join1, sr);
        let b2 = click_ratio(ch, join2, sr);
        assert!(a < 1.5 && b2 < 1.5, "join ratios {a} {b2}");
    }
    // a hard splice at the same points clicks (validates the detector)
    // (half a period removed at a peak: the splice jumps from +peak to -peak)
    let hard = ok_t("cut", &[("range", "24027smp..24082smp"), ("crossfade", "0ms")], b);
    assert!(click_ratio(&hard.data[0], 24027, sr) > 3.0);
}

#[test]
fn cut_edge_cases() {
    let b = sine(8000, 300.0, 1.0, 0.5);
    // overlapping ranges merge
    let out = ok_t("cut", &[("range", "0.1s..0.3s"), ("range", "0.2s..0.4s")], b.clone());
    assert_eq!(out.frames(), 8000 - 2400);
    // removing the start keeps the remainder (with a fade only if the new edge would click)
    let out = ok_t("cut", &[("range", "start..0.25s")], b.clone());
    assert_eq!(out.frames(), 6000);
    // removing everything is an error
    assert_eq!(err_code(run_t("cut", &[("range", "0s..end")], b.clone()).0), 2);
    assert_eq!(err_code(run_t("cut", &[("range", "0.5s..0.4s")], b.clone()).0), 2);
    // equal-power crossfade of a constant signal: sqrt(2)/2 + sqrt(2)/2 at the middle
    let dc = AudioBuffer::from_mono(1000, vec![0.5; 1000]);
    let out = ok_t("cut", &[("range", "0.4s..0.6s"), ("crossfade", "100ms")], dc.clone());
    assert_eq!(out.frames(), 800);
    let mid = out.data[0][400];
    assert!((mid - 0.5 * std::f32::consts::SQRT_2).abs() < 0.01, "{mid}");
    let out = ok_t("cut", &[("range", "0.4s..0.6s"), ("crossfade", "100ms"), ("crossfade-curve", "linear")], dc);
    assert!(out.data[0].iter().all(|v| (v - 0.5).abs() < 1e-5));
}

