// normalize
// ---------------------------------------------------------------------------------------

fn assert_normalized(out: &AudioBuffer, target: f64, ceiling_db: f64) {
    let l = loudness::integrated_lufs(out).unwrap();
    assert!((l - target).abs() <= 0.3, "loudness {l} vs {target}");
    let c = db(ceiling_db);
    let tp = loudness::true_peak(out);
    let tpe = loudness::true_peak_ebur128(out).unwrap();
    assert!(tp <= c, "own true peak {} dBTP over {ceiling_db}", lin_to_db(tp as f64));
    assert!(tpe <= c, "ebur128 true peak {} dBTP over {ceiling_db}", lin_to_db(tpe as f64));
}

#[test]
fn normalize_sine_to_minus_14() {
    let b = stereo(sine(48000, 1000.0, 8.0, db(-30.0)));
    let (out, c) = run_t("normalize", &[], b);
    let out = out.unwrap();
    assert_normalized(&out, -14.0, -1.0);
    assert!(c.metrics.contains_key("before") && c.metrics.contains_key("after"));
    let after = c.metrics["after"]["integrated_lufs"].as_f64().unwrap();
    assert!((after + 14.0).abs() <= 0.3);
    assert!(!c.metrics.contains_key("limiter"), "a -14 LUFS sine needs no limiting");
}

#[test]
fn normalize_pink_noise() {
    let b = stereo(pink(48000, 8.0, 0.3, 3));
    let out = ok_t("normalize", &[("lufs", "-16")], b);
    assert_normalized(&out, -16.0, -1.0);
}

#[test]
fn normalize_loud_signal_requires_limiting() {
    // pink noise pushed to -9 LUFS: its peaks would reach well above -1 dBTP
    let b = stereo(pink(48000, 8.0, 0.3, 11));
    let (out, c) = run_t("normalize", &[("lufs", "-9")], b);
    let out = out.unwrap();
    assert_normalized(&out, -9.0, -1.0);
    let gr = c.metrics["limiter"]["max_gain_reduction_db"].as_f64().unwrap();
    assert!(gr > 1.0, "limiter should have worked: {gr} dB");
    // sharp transients over a steady bed: the bed sets the loudness, the transients the
    // peaks, so -14 LUFS is only reachable with limiting
    let sr = 48000;
    let mut x = vec![0f32; sr * 8];
    let burst = noise(sr as u32, 0.01, 1.0, 5);
    for k in 0..16 {
        let start = k * sr / 2;
        for (i, v) in burst.data[0].iter().enumerate() {
            x[start + i] += v * (-(i as f32) / 60.0).exp();
        }
    }
    let bed = pink(sr as u32, 8.0, 0.25, 9);
    for (o, v) in x.iter_mut().zip(&bed.data[0]) {
        *o += v;
    }
    let b = stereo(AudioBuffer::from_mono(sr as u32, x));
    let (out, c) = run_t("normalize", &[("lufs", "-14"), ("ceiling", "-1.5dBTP")], b);
    assert_normalized(&out.unwrap(), -14.0, -1.5);
    assert!(c.metrics.contains_key("limiter"));
}

#[test]
fn normalize_unreachable_target_warns_but_holds_ceiling() {
    // a stereo 1 kHz sine reads LUFS equal to its peak in dBFS, so -0.5 LUFS needs
    // -0.5 dBTP peaks: above the -1 dBTP ceiling
    let b = stereo(sine(48000, 1000.0, 4.0, 0.1));
    let (out, c) = run_t("normalize", &[("lufs", "-0.5")], b);
    let out = out.unwrap();
    assert!(has_warning(&c, "target_not_reached"));
    assert!(loudness::true_peak_conservative(&out).unwrap() <= db(-1.0));
}

#[test]
fn normalize_peak_and_rms_modes() {
    let b = stereo(pink(48000, 3.0, 0.2, 21));
    let out = ok_t("normalize", &[("peak", "-1dBTP")], b.clone());
    let tp = lin_to_db(loudness::true_peak_conservative(&out).unwrap() as f64);
    assert!(tp <= -1.0 && tp > -1.05, "true peak {tp}");
    let out = ok_t("normalize", &[("peak", "-3dB")], b.clone());
    assert!((lin_to_db(out.peak() as f64) + 3.0).abs() < 1e-3);
    let s = sine(48000, 500.0, 2.0, 0.1);
    let out = ok_t("normalize", &[("rms", "-20dB")], s);
    assert!((loudness::rms_db(&out) + 20.0).abs() < 0.05);
}

#[test]
fn normalize_modes_conflict_and_edge_cases() {
    let b = sine(48000, 1000.0, 2.0, 0.1);
    assert_eq!(err_code(run_t("normalize", &[("lufs", "-14"), ("peak", "-1dBTP")], b.clone()).0), 2);
    assert_eq!(err_code(run_t("normalize", &[("peak", "-1dB"), ("rms", "-20dB")], b.clone()).0), 2);
    // silence is left alone with a warning
    let (out, c) = run_t("normalize", &[], AudioBuffer::new(48000, 2, 4800));
    assert_eq!(out.unwrap().peak(), 0.0);
    assert!(has_warning(&c, "silent_input"));
    // empty input
    let (out, _) = run_t("normalize", &[], AudioBuffer::new(48000, 1, 0));
    assert!(out.unwrap().is_empty());
    // limiter off: true peak over the ceiling is reported
    let loud = stereo(pink(48000, 4.0, 0.3, 4));
    let (out, c) = run_t("normalize", &[("lufs", "-8"), ("true-peak-limit", "off")], loud);
    let out = out.unwrap();
    assert!(loudness::true_peak(&out) > db(-1.0));
    assert!(has_warning(&c, "true_peak_over_ceiling"));
    // very short input (under one gating block) still normalizes, with a warning
    let short = sine(48000, 1000.0, 0.2, 0.05);
    let (out, c) = run_t("normalize", &[("lufs", "-20")], short);
    let l = loudness::integrated_lufs(&out.unwrap()).unwrap();
    assert!((l + 20.0).abs() < 0.3, "{l}");
    assert!(has_warning(&c, "short_input"));
    // mix 0% is the identity, bit for bit
    let s = stereo(pink(48000, 3.0, 0.2, 8));
    assert_eq!(ok_t("normalize", &[("mix", "0%")], s.clone()), s);
}

#[test]
fn normalize_batch_matches_loudness() {
    use ferraus_core::ctx::{CancelToken, Globals};
    use ferraus_core::exec::{Invocation, Runtime};
    let dir = TempDir::new("match-loudness");
    let quiet = stereo(pink(48000, 4.0, 0.05, 1));
    let loud = stereo(sine(48000, 220.0, 4.0, 0.7));
    write_wav(&dir.path("a.wav"), &quiet);
    write_wav(&dir.path("b.wav"), &loud);
    let registry = testing::leak_registry(crate::ops());
    let presets = |_: &str, _: &str| -> Option<Vec<(String, String)>> { None };
    let rt = Runtime {
        registry,
        io: &testing::SIMPLE_IO,
        progress: &testing::NO_PROGRESS,
        presets: &presets,
        cancel: CancelToken::default(),
    };
    let outdir = dir.path("out");
    let globals = Globals { outdir: Some(outdir.clone()), ..Globals::default() };
    let o = rt.invoke(Invocation {
        command: "normalize".into(),
        args: vec![("lufs".into(), "-18".into())],
        inputs: vec![dir.path("a.wav").display().to_string(), dir.path("b.wav").display().to_string()],
        globals,
        ..Default::default()
    });
    assert!(o.envelope.ok, "{:?}", o.envelope.error);
    assert_eq!(o.envelope.outputs.len(), 2);
    for rec in &o.envelope.outputs {
        let b = read_wav(std::path::Path::new(&rec.path));
        let l = loudness::integrated_lufs(&b).unwrap();
        assert!((l + 18.0).abs() <= 0.3, "{} at {l}", rec.path);
    }
    // per-file metrics in the batch result
    let items = o.envelope.result.as_array().unwrap();
    assert!(items[0]["metrics"]["before"]["integrated_lufs"].is_number());
}

