#[test]
fn channels_operations() {
    let l = vec![0.5f32, -0.25, 1.0];
    let r = vec![0.1f32, 0.3, -1.0];
    let b = AudioBuffer::from_planar(8000, vec![l.clone(), r.clone()]);
    let mono = ok_t("channels", &[("to", "mono")], b.clone());
    assert_eq!(mono.channels(), 1);
    for (x, y) in mono.data[0].iter().zip([0.3f32, 0.025, 0.0]) {
        assert!((x - y).abs() < 1e-6);
    }
    let st = ok_t("channels", &[("to", "stereo")], mono.clone());
    assert_eq!(st.data, vec![mono.data[0].clone(), mono.data[0].clone()]);
    assert_eq!(ok_t("channels", &[("extract", "R")], b.clone()).data, vec![r.clone()]);
    assert_eq!(ok_t("channels", &[("extract", "1")], b.clone()).data, vec![l.clone()]);
    assert_eq!(ok_t("channels", &[("swap", "true")], b.clone()).data, vec![r.clone(), l.clone()]);
    let ms = ok_t("channels", &[("mid-side", "encode")], b.clone());
    assert!((ms.data[0][0] - 0.3).abs() < 1e-7 && (ms.data[1][0] - 0.2).abs() < 1e-7);
    let back = ok_t("channels", &[("mid-side", "decode")], ms);
    for (x, y) in back.data.iter().flatten().zip(b.data.iter().flatten()) {
        assert!((x - y).abs() < 1e-6);
    }
    // 5.1 fold-down
    let six = AudioBuffer::from_planar(8000, (0..6).map(|c| vec![c as f32 * 0.1]).collect());
    let st = ok_t("channels", &[("to", "stereo")], six);
    let k = std::f32::consts::FRAC_1_SQRT_2;
    assert!((st.data[0][0] - (0.0 + k * 0.2 + k * 0.4)).abs() < 1e-6);
    assert!((st.data[1][0] - (0.1 + k * 0.2 + k * 0.5)).abs() < 1e-6);
}

#[test]
fn channels_errors() {
    let m = sine(8000, 440.0, 0.1, 0.5);
    let s = stereo(m.clone());
    assert_eq!(err_code(run_t("channels", &[], s.clone()).0), 2);
    assert_eq!(err_code(run_t("channels", &[("to", "mono"), ("swap", "true")], s.clone()).0), 2);
    assert_eq!(err_code(run_t("channels", &[("extract", "3")], s.clone()).0), 2);
    assert_eq!(err_code(run_t("channels", &[("extract", "0")], s).0), 2);
    assert_eq!(err_code(run_t("channels", &[("swap", "true")], m.clone()).0), 2);
    assert_eq!(err_code(run_t("channels", &[("mid-side", "encode")], m.clone()).0), 2);
    assert_eq!(ok_t("channels", &[("to", "mono")], m.clone()), m);
}

