#[test]
fn concat_crossfade_length_math() {
    let sr = 8000;
    let a = sine(sr, 440.0, 1.0, 0.5);
    let b = sine(sr, 660.0, 1.0, 0.5);
    let c = sine(sr, 880.0, 0.5, 0.5);
    let (r, ctx, dir) =
        run_custom("concat", &[("crossfade", "100ms")], &[a.clone(), b.clone(), c.clone()], Some("out.wav"), |_| {});
    let v = r.unwrap();
    let out = read_wav(&dir.path("out.wav"));
    assert_eq!(out.frames(), 8000 + 8000 + 4000 - 2 * 800);
    assert_eq!(v["joins"].as_array().unwrap().len(), 2);
    assert_eq!(ctx.outputs.len(), 1);
    // gap
    let (_, _, dir) = run_custom("concat", &[("gap", "250ms")], &[a.clone(), b.clone()], Some("g.wav"), |_| {});
    let out = read_wav(&dir.path("g.wav"));
    assert_eq!(out.frames(), 16000 + 2000);
    assert_eq!(out.slice(0, 8000), a);
    assert!(out.data[0][8000..10000].iter().all(|v| *v == 0.0));
    // crossfade longer than a file is shortened with a warning
    let short = sine(sr, 440.0, 0.05, 0.5);
    let (_, ctx, dir) = run_custom("concat", &[("crossfade", "1s")], &[a.clone(), short], Some("s.wav"), |_| {});
    assert_eq!(read_wav(&dir.path("s.wav")).frames(), 8000);
    assert!(has_warning(&ctx, "crossfade_shortened"));
    // linear crossfade of two constants is flat
    let k = AudioBuffer::from_mono(sr, vec![0.5; 4000]);
    let (_, _, dir) = run_custom(
        "concat",
        &[("crossfade", "100ms"), ("crossfade-curve", "linear")],
        &[k.clone(), k.clone()],
        Some("k.wav"),
        |_| {},
    );
    assert!(read_wav(&dir.path("k.wav")).data[0].iter().all(|v| (v - 0.5).abs() < 1e-6));
}

